export const guides=[
 {id:'arc:camera',code:'01',name:'Камера из старых модулей',category:'vision',icon:'camera',time:'1–2 часа',level:'С настройкой',summary:'Верни к жизни Raspberry Pi и модуль камеры. Снимки сохраняются на карту, облако не нужно.',bom:bom('pi','csi','sd'),tools:['Компьютер для записи ОС','Картридер','Изолирующее крепление'],flow:['CSI-камера','Raspberry Pi','Карта памяти'],steps:[['Подготовь плату','Запиши актуальную Raspberry Pi OS на microSD через Raspberry Pi Imager. Сначала скопируй данные с карты. Подключи штатное питание платы.'],['Подключи камеру','Полностью обесточь Pi. Для Pi 3/4 используй 15-контактный шлейф CSI. Вставь его по инструкции производителя и закрой фиксаторы.'],['Проверь изображение','Загрузи систему. Выполни rpicam-hello --list-cameras, затем rpicam-still -o test.jpg. Убедись, что файл читается и изображение резкое.'],['Зафиксируй сборку','Закрепи плату на изолирующих стойках. Оставь вентиляцию и доступ к карте. Для улицы нужен подходящий корпус; этот план рассчитан на сухое помещение.']],check:'После перезапуска снова получи снимок и открой его с карты. Это фотокамера; запись по движению — отдельная сборка.',sources:[['Камеры и подключение · Raspberry Pi','https://www.raspberrypi.com/documentation/accessories/camera.html'],['Команды rpicam · Raspberry Pi','https://www.raspberrypi.com/documentation/computers/camera_software.html']],note:'План по документации производителя. Физическая сборка не испытана.'},
 {id:'arc:watch',code:'02',name:'Наблюдение без облака',category:'vision',icon:'monitor',time:'1–3 часа',level:'С настройкой',summary:'USB-камера и забытый ноутбук становятся локальным постом наблюдения с записью движения.',bom:bom('laptop','webcam','router'),tools:['Linux на ноутбуке','Программа Motion','Место на диске'],flow:['USB-камера','Ноутбук + Motion','Локальная сеть'],steps:[['Проверь камеру','Подключи готовую USB UVC-камеру. Найди устройство /dev/video* и открой изображение в приложении камеры.'],['Настрой Motion','Установи Motion из репозитория своей Linux-системы. В отдельном конфиге укажи video_device и каталог target_dir с правом записи. Начни с 640 × 480 и 5 кадров/с.'],['Проверь запись','Запусти Motion в терминале с этим конфигом. Пройди перед камерой, затем проверь созданные файлы. Настрой threshold под помещение.'],['Открой локальный просмотр','Для доступа из своей сети настрой stream_port и stream_localhost по документации Motion. Задай stream_auth_method и stream_authentication. На роутере не включай проброс портов.']],check:'Проверь просмотр с другого устройства в своей Wi-Fi сети, запись события и свободное место на диске.',sources:[['Настройка Motion · официальный проект','https://motion-project.github.io/motion_config.html']],note:'Камера для своего помещения. План по документации; аппаратное испытание не проводилось.'},
 {id:'arc:alarm',code:'03',name:'Сигнализация на дверь',category:'security',icon:'alarm',time:'40–90 минут',level:'Базовая пайка',summary:'Магнитный контакт, Arduino и пьезоэлемент. Открылась дверь — прозвучал сигнал.',bom:bom('uno','reed','piezo','wires'),tools:['Компьютер с Arduino IDE','Мультиметр','Крепление для датчика'],flow:['Геркон → D2','Arduino Uno','D8 → пьезо'],steps:[['Проверь контакт','Без питания прозвони геркон: рядом с магнитом он должен замыкаться. Отметь положение магнита.'],['Соедини на макете','Обесточь Arduino. Подключи геркон между D2 и GND. Подключи малый пассивный пьезоэлемент между D8 и GND. Программа использует INPUT_PULLUP.'],['Загрузи пример','Скачай скетч из этой карточки и загрузи его на Uno. Держи магнит рядом с герконом при запуске. Убери магнит — должен прозвучать сигнал.'],['Установи на дверь','Закрепи геркон на раме, магнит на двери. Изолируй контакты и закрепи провода. Питай Arduino через штатный USB-разъём.']],check:'Десять раз открой и закрой дверь. Проверь, что закрытая дверь не вызывает сигнал, а открытая вызывает его устойчиво.',firmware:'assets/door-alarm.ino',sources:[['INPUT_PULLUP · Arduino','https://docs.arduino.cc/built-in-examples/digital/InputPullupSerial/'],['Звук tone · Arduino','https://docs.arduino.cc/built-in-examples/digital/toneMelody/']],note:'Учебная сигнализация. Не заменяет сертифицированную охранную систему; скетч не проверен на физической плате.'},
 {id:'arc:wick',code:'04',name:'Полив без электричества',category:'water',icon:'plant',time:'20–40 минут',level:'Без пайки',summary:'Банка, хлопковый фитиль и поддон. Маленькая автономная система для одного горшка.',bom:bom('jar','wick','tray'),tools:['Ножницы','Мерная ёмкость'],flow:['Запас воды','Влажный фитиль','Почва'],steps:[['Подготовь фитиль','Возьми чистый хлопковый шнур, намочи целиком. Проверь, что он впитывает воду.'],['Собери контур','Один конец опусти в устойчивую ёмкость с водой, второй заглуби во влажную почву. Начни с уровня воды немного ниже поверхности почвы.'],['Добавь поддон','Поставь ёмкость и горшок в поддон. Убедись, что фитиль не выпадает, а сосуд нельзя легко опрокинуть.'],['Подбери расход','Наблюдай 2–3 дня: отмечай уровень воды и влажность земли. Меняй толщину фитиля или высоту ёмкости. Универсального срока автономности нет.']],check:'Сначала проведи несколько дней испытаний дома. Почва должна оставаться подходящей растению влажности, без луж.',sources:[['Исходная идея фитильного полива · jjdebenedictis','https://www.instructables.com/A-Cheap-Easy-Leak-Safe-Way-to-Water-Plants-While-O/']],archiveId:'prj:a-cheap-easy-leak-safe-way-to-water-plants-while-o',note:'Адаптация идеи из найденного архива. Фактический расход зависит от растения, грунта и фитиля.'},
 {id:'arc:pump',code:'05',name:'Полив по таймеру',category:'water',icon:'pump',time:'1–2 часа',level:'Готовые модули',summary:'USB-помпа и интервальный таймер дозируют воду из ёмкости. Вся цепь работает на 5 В.',bom:bom('usbpower','pump','timer','tube','jar','tray'),tools:['Мерная ёмкость','Таймер или секундомер'],flow:['USB 5 В','Таймер → помпа','Шланг → растение'],steps:[['Сверь модули','Проверь маркировку: источник, таймер и помпа должны работать на 5 В. Допустимый ток источника и таймера должен покрывать пусковой ток помпы.'],['Собери воду','Соедини помпу и шланг по инструкции помпы. Размести ёмкость ниже выхода шланга, чтобы вода не текла самотёком после остановки. Всё поставь в поддон.'],['Измерь расход','Включи помпу на 10 секунд и измерь объём в мерном стакане. По этому результату рассчитай время для нужной порции воды. Не запускай помпу всухую, если это запрещено её инструкцией.'],['Настрой интервал','Подключи готовые USB-разъёмы: питание → таймер → помпа. Начни с малого объёма и проверь несколько циклов в присутствии. Настрой интервал по потребностям растения.']],check:'После отключения вода должна останавливаться. Проверь утечки, нагрев разъёмов и восстановление таймера после пропадания питания.',sources:[],note:'План на готовых модулях. Конкретные модели и их инструкции нужно сверить до сборки; физическое испытание не проводилось.'},
 {id:'arc:light',code:'06',name:'Свет на случай отключения',category:'energy',icon:'light',time:'10–20 минут',level:'Без пайки',summary:'Исправный пауэрбанк и USB-лампа превращаются в переносной свет для рабочего места.',bom:bom('powerbank','lamp'),tools:['Устойчивое крепление'],flow:['Пауэрбанк','USB 5 В','Готовый LED-светильник'],steps:[['Осмотри питание','Возьми целый готовый пауэрбанк без вздутия и повреждений. Проверь маркировку USB-выхода.'],['Подключи свет','Подключи готовую USB-лампу на 5 В. Закрепи её устойчиво, не закрывая вентиляционные отверстия.'],['Проверь автоотключение','Оставь свет на 30 минут: некоторые пауэрбанки отключают слишком малую нагрузку. При отключении подбери совместимый готовый светильник или пауэрбанк.'],['Измерь автономность','Проведи полный пробный цикл и запиши реальное время работы. Заряди комплект и держи его вместе.']],check:'Свет не мерцает, питание не отключается, разъёмы не перегреваются.',sources:[],note:'Совместимость определяется маркировкой устройств и пробным запуском. Не требует разборки аккумуляторов.'},
 {id:'arc:fan',code:'07',name:'Вентиляция рабочего места',category:'energy',icon:'fan',time:'10–20 минут',level:'Без пайки',summary:'Настольный USB-вентилятор снова работает от внешнего аккумулятора.',bom:bom('powerbank','fan'),tools:['Устойчивое основание'],flow:['Пауэрбанк','USB 5 В','Вентилятор'],steps:[['Проверь напряжение','Используй готовый вентилятор с USB-входом на 5 В и защитной решёткой.'],['Очисти и закрепи','При отключённом питании убери пыль. Зафиксируй устройство на ровной поверхности.'],['Запусти','Подключи к пауэрбанку. Проверь запуск и работу на всех доступных режимах.'],['Испытай','Проверь через 30 минут нагрев корпуса и устойчивость. Измерь доступное время работы.']],check:'Лопасти не задевают решётку, провод не попадает в них. Это бытовой обдув, не вытяжка для вредных паров.',sources:[],note:'План на готовых устройствах. Кулер на 12 В не подставляется как эквивалент.'},
 {id:'arc:library',code:'08',name:'Архив знаний в локальной сети',category:'info',icon:'server',time:'30–60 минут',level:'С настройкой',summary:'Ноутбук, роутер и флешка. Инструкции доступны соседним устройствам даже без интернета.',bom:bom('laptop','router','storage'),tools:['Python 3','Подготовленные HTML / PDF / текстовые файлы'],flow:['USB-архив','Ноутбук','Wi-Fi → браузеры'],steps:[['Подготовь папку','Скопируй только файлы, которыми хочешь делиться, в отдельную папку. Не размещай рядом личные документы.'],['Запусти просмотр','В этой папке выполни python3 -m http.server 8080 --bind 0.0.0.0. Сервер раздаёт содержимое папки на чтение.'],['Подключи устройства','Подключи ноутбук и телефон к своему роутеру. В браузере телефона открой http://ЛОКАЛЬНЫЙ-IP-НОУТБУКА:8080.'],['Проверь без интернета','Отключи WAN-кабель роутера и открой инструкцию на телефоне. Останови сервер сочетанием Ctrl+C, когда он больше не нужен.']],check:'Проверь файлы с другого устройства. Сервер не имеет пароля: используй доверенную локальную сеть и не делай проброс портов.',sources:[['http.server · Python','https://docs.python.org/3/library/http.server.html']],note:'Простой сервер для доверенной локальной сети. Ноутбук должен оставаться включённым.'}
];
export const kits=[{name:'Старая электроника',ids:['laptop','webcam','router']},{name:'Ящик Arduino',ids:['uno','wires','piezo']},{name:'Всё для простого полива',ids:['jar','wick','tray']}];
export const partById=Object.fromEntries(parts.map(p=>[p.id,p]));
